@Experiments.AbstractLoopsPostprocessing.scheduled_iteration_preserves_kernel : ∀ {World State : Type}
  (step : ℕ → State → State) (initial : World → State) (n : ℕ) (first second : World),
  Experiments.AbstractLoopsPostprocessing.scheduledIteration step initial n first =
      Experiments.AbstractLoopsPostprocessing.scheduledIteration step initial n second →
    Experiments.AbstractLoopsPostprocessing.scheduledIteration step initial (n + 1) first =
      Experiments.AbstractLoopsPostprocessing.scheduledIteration step initial (n + 1) second

@Experiments.AbstractLoopsPostprocessing.finite_relation_chain_stabilizes : ∀ {α : Type} [Fintype α] [DecidableEq α]
  (relations : ℕ → Finset α),
  (∀ (n : ℕ), relations n ⊆ relations (n + 1)) → ∃ start, ∀ (n : ℕ), start ≤ n → relations start = relations n
